```c
/* functions.c */
#include <stdio.h>

int add(int a, int b);
int triple(int x);

void swap_values(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int sum_of(const int *values, size_t count) {
    int total = 0;
    size_t i;
    for (i = 0; i < count; ++i) {
        total += values[i];
    }
    return total;
}

int add(int a, int b) {
    return a + b;
}

int triple(int x) {
    return x * 3;
}

int main(void) {
    int x = 2, y = 1;
    swap_values(&x, &y);
    printf("after swap : %d %d\n", x, y);

    int values[5] = {1, 2, 3, 4, 5};
    printf("sum         : %d\n", sum_of(values, 5));

    printf("add(3, 4)   : %d\n", add(3, 4));
    printf("triple(7)   : %d\n", triple(7));

    /* A function cannot change a caller's int without a pointer. */
    int n = 5;
    printf("before      : %d\n", n);

    return 0;
}
```

